"The appearances of the Virgin Mary that the Church has recognized, from Guadalupe to Kibeho, and how the Church discerns them.": "Le apparizioni della Vergine Maria riconosciute dalla Chiesa, da Guadalupe a Kibeho, e come la Chiesa le discerne.",
"From the Council of Clermont to the Siege of Malta: the crusades, the knightly orders they created, and how the Church remembers them today.": "Dal Concilio di Clermont all’assedio di Malta: le crociate, gli ordini cavallereschi che ne nacquero e come la Chiesa le ricorda oggi.",
"Every prayer, saint, book, event, and teaching in Sanctify, in one list.": "Tutte le preghiere, i santi, i libri, gli eventi e gli insegnamenti di Sanctify, in un unico elenco.",
"A guided examination of conscience to prepare for the Sacrament of Reconciliation, following the Ten Commandments.": "Un esame di coscienza guidato per prepararsi al sacramento della Riconciliazione, seguendo i Dieci Comandamenti.",
"Announcements and updates from the Sanctify team.": "Annunci e novità dal team di Sanctify.",
"Badges for prayer, reading, and the Community, with your progress toward each.": "Distintivi per la preghiera, la lettura e la Comunità, con i tuoi progressi verso ciascuno.",
"Reports, accounts, bans, and the moderation log.": "Segnalazioni, account, ban e registro di moderazione.",
"Read through the Gospels, the Psalms, the New Testament, or the whole Bible, a little each day.": "Leggi i Vangeli, i Salmi, il Nuovo Testamento o tutta la Bibbia, un po’ ogni giorno.",
"Your saved entries, prayer intentions, and novenas. Everything here stays private, stored only in this browser.": "Le voci salvate, le intenzioni di preghiera e le novene. Tutto resta privato, salvato solo in questo browser.",
"Set aside time for silent prayer, meditation, or a Holy Hour, with a gentle bell to begin and end.": "Dedica del tempo alla preghiera silenziosa, alla meditazione o a un’Ora Santa, con una campana delicata all’inizio e alla fine.",
"Test what you know about the saints, Scripture, Church history, and great Catholic books.": "Metti alla prova ciò che sai sui santi, la Scrittura, la storia della Chiesa e i grandi libri cattolici.",
"Every prayer as an illustrated prayer card. Choose a topic, then open a card to pray it, save it, or print it.": "Ogni preghiera come un santino illustrato. Scegli un tema, poi apri un santino per pregarlo, salvarlo o stamparlo.",
"The prayer St. Ignatius never wanted his companions to skip: five short steps to look back on the day with God.": "La preghiera che sant’Ignazio non voleva mai che i suoi compagni tralasciassero: cinque brevi passi per rileggere la giornata con Dio.",
"Gregorian chant and beloved Catholic hymns, with recordings and the words in Latin and English: the Salve Regina, Pange Lingua, Veni Creator, Adeste Fideles, and more.": "Canto gregoriano e amati inni cattolici, con registrazioni e testi in latino e in inglese: il Salve Regina, il Pange Lingua, il Veni Creator, l’Adeste Fideles e altri.",
"The Hours of Our Lady, from Matins to Compline, following the seasons of the year. A beloved prayer of religious, tertiaries, and those who wear the Brown Scapular.": "Le Ore della Madonna, dal Mattutino alla Compieta, secondo i tempi dell’anno. Una preghiera cara ai religiosi, ai terziari e a chi porta lo scapolare del Carmine.",
"The Brown and Green Scapulars, the Miraculous and St. Benedict Medals, First Fridays and First Saturdays, and holy water: what each one is, how to keep it, and its prayers.": "Lo scapolare del Carmine e quello verde, la Medaglia miracolosa e quella di san Benedetto, i primi venerdì e i primi sabati, e l’acqua benedetta: che cos’è ciascuno, come viverlo e le sue preghiere.",
"The ancient prayer of the Incarnation, prayed at morning, noon, and evening. During the Easter season, the Regina Caeli.": "L’antica preghiera dell’Incarnazione, recitata al mattino, a mezzogiorno e alla sera. Nel tempo pasquale, il Regina Caeli.",
"Pray with a passage of Scripture the way the monks did: read, reflect, respond, and rest in God.": "Prega con un passo della Scrittura come facevano i monaci: leggere, meditare, rispondere e riposare in Dio.",
"Keep a private record of your daily prayer, build a steady habit, and see your faithfulness over the weeks.": "Tieni un diario privato della tua preghiera quotidiana, crea un’abitudine costante e guarda la tua fedeltà nelle settimane.",
"Every part of the Mass in order, with when to stand, sit, and kneel, and what each moment means. Follow along on your phone at Mass.": "Ogni parte della Messa in ordine, con quando alzarsi, sedersi e inginocchiarsi, e il significato di ogni momento. Seguila sul telefono durante la Messa.",
"Every pope from St. Peter to Leo XIV, century by century.": "Tutti i papi, da san Pietro a Leone XIV, secolo per secolo.",
"The great religious orders of the Church: monks, canons, friars, clerks regular, sisters, and the military orders of the crusades.": "I grandi ordini religiosi della Chiesa: monaci, canonici, frati, chierici regolari, suore e gli ordini militari delle crociate.",
"The most famous icons of East and West, what they show, and the stories behind them.": "Le icone più famose d’Oriente e d’Occidente, cosa raffigurano e le loro storie.",
"The twenty-three Eastern Catholic Churches, in full communion with Rome: their traditions, leaders, and lands.": "Le ventitré Chiese cattoliche orientali, in piena comunione con Roma: le loro tradizioni, i loro pastori e le loro terre.",
"How to become Catholic or come home, the basics of everyday Catholic life, and guides to discerning and living each vocation: marriage, priesthood, religious life, and more.": "Come diventare cattolici o tornare a casa, le basi della vita cattolica quotidiana e guide per discernere e vivere ogni vocazione: matrimonio, sacerdozio, vita religiosa e altre.",
"The lists every Catholic learns, explained: the Ten Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more.": "Gli elenchi che ogni cattolico impara, spiegati: i Dieci Comandamenti, le Beatitudini, i precetti, i sacramenti, le virtù, le opere di misericordia, i vizi capitali e altri.",
"A walk through a Catholic church: what each part is for, the sacred vessels, the vestments, the colors of the seasons, and how to take part in the Mass.": "Una visita in una chiesa cattolica: a cosa serve ogni parte, i vasi sacri, i paramenti, i colori dei tempi e come partecipare alla Messa.",
"All twenty-one ecumenical councils, from Nicaea to Vatican II: when and where they met, and what each one taught.": "Tutti i ventuno concili ecumenici, da Nicea al Vaticano II: quando e dove si riunirono e che cosa insegnò ciascuno.",
"Clear, short definitions of the words of the Catholic faith, from Absolution to the Vulgate.": "Definizioni brevi e chiare delle parole della fede cattolica, da «assoluzione» a «Vulgata».",
"The words of the saints, from the Church Fathers to our own day, each with its source. Search them, browse by theme, and share your favorites.": "Le parole dei santi, dai Padri della Chiesa ai nostri giorni, ognuna con la sua fonte. Cercale, sfogliale per tema e condividi le tue preferite.",
"Pick as many answers as you like: your name, your work, your needs, and what you love in a saint. Sanctify suggests friends in heaven who fit.": "Scegli tutte le risposte che vuoi: il tuo nome, il tuo lavoro, le tue necessità e ciò che ami in un santo. Sanctify ti suggerisce amici in cielo adatti a te.",
"Trusted places to keep learning about the faith: Church documents, Scripture and prayer, podcasts, video, courses, and more.": "Luoghi affidabili per continuare a conoscere la fede: documenti della Chiesa, Scrittura e preghiera, podcast, video, corsi e altro.",
"Share prayer requests, ask questions about the faith, and talk about the saints and good books with other Sanctify members.": "Condividi richieste di preghiera, fai domande sulla fede e parla dei santi e dei buoni libri con altri membri di Sanctify.",
