"Read Sanctify in your language. Pages are translated by Google, by machine: prayers and Scripture may not match the approved translations used in your country, and Latin texts stay in Latin.": "Leggi Sanctify nella tua lingua. Le pagine sono tradotte automaticamente da Google: le preghiere e la Scrittura possono non coincidere con le traduzioni approvate nel tuo paese, e i testi latini restano in latino.",
"Find a language…": "Cerca una lingua…",
"A Catholic Repository": "Una raccolta cattolica",
"The Mass and calendar of the Roman Rite as celebrated in most parishes today.": "La Messa e il calendario del rito romano come si celebrano oggi nella maggior parte delle parrocchie.",
"The Missal and calendar of 1962: the Traditional Latin Mass explained, the old feasts, seasons, and Ember Days, and the fifteen mysteries of the Rosary.": "Il Messale e il calendario del 1962: la Messa tradizionale in latino spiegata, le antiche feste, i tempi e le Quattro Tempora, e i quindici misteri del Rosario.",
"The Byzantine tradition: the Divine Liturgy, the Jesus Prayer, Byzantine prayers, and the Byzantine calendar.": "La tradizione bizantina: la Divina Liturgia, la preghiera di Gesù, le preghiere bizantine e il calendario bizantino.",
