"because by Your holy cross You have redeemed the world.": "perché con la tua santa croce hai redento il mondo.",
"We adore You, O Christ, and we bless You, because by Your holy cross You have redeemed the world.": "Ti adoriamo, o Cristo, e ti benediciamo, perché con la tua santa croce hai redento il mondo.",
