"The Mass and Divine Office of the day in Latin and English (Divinum Officium) ↗": "La Messa e l’Ufficio divino del giorno in latino e inglese (Divinum Officium) ↗",
"Pray the Rosary bead by bead with the fifteen traditional mysteries, Joyful, Sorrowful, and Glorious, and a meditation for each.": "Prega il Rosario grano per grano con i quindici misteri tradizionali, gaudiosi, dolorosi e gloriosi, e una meditazione per ciascuno.",
