"{n} prayers as illustrated cards, the Jesus Prayer on a prayer rope, the Trisagion Prayers, and the Prayer of St. Ephrem.": "{n} preghiere in santini illustrati, la preghiera di Gesù sulla corda di preghiera, le preghiere del Trisagio e la preghiera di sant’Efrem.",
