". The Community Wiki is written by members and isn’t official Church teaching; check what matters against the Catechism and your pastor.": ". La wiki della comunità è scritta dai membri e non è insegnamento ufficiale della Chiesa; verifica ciò che conta con il Catechismo e con il tuo parroco.",
"Started {*}. The Community Wiki is written by members and isn’t official Church teaching; check what matters against the Catechism and your pastor.": "Avviata il {*}. La wiki della comunità è scritta dai membri e non è insegnamento ufficiale della Chiesa; verifica ciò che conta con il Catechismo e con il tuo parroco.",
