"Sts. Thomas Aquinas, Albert the Great, Catherine of Siena, Rose of Lima, Martin de Porres, Pius V": "San Tommaso d’Aquino, sant’Alberto Magno, santa Caterina da Siena, santa Rosa da Lima, san Martino de Porres, san Pio V",
"c. 1206–1214 (rule)": "ca. 1206–1214 (regola)",
"Sts. Teresa of Ávila, John of the Cross, Thérèse of Lisieux, Edith Stein, Elizabeth of the Trinity": "Santa Teresa d’Avila, san Giovanni della Croce, santa Teresa di Lisieux, santa Edith Stein, santa Elisabetta della Trinità",
"Sts. Rita of Cascia, Nicholas of Tolentino, Thomas of Villanova, Clare of Montefalco": "Santa Rita da Cascia, san Nicola da Tolentino, san Tommaso da Villanova, santa Chiara da Montefalco",
"The Seven Holy Founders, Sts. Philip Benizi, Peregrine Laziosi, Juliana Falconieri": "I Sette Santi Fondatori, san Filippo Benizi, san Pellegrino Laziosi, santa Giuliana Falconieri",
"Sts. John of Matha and Felix of Valois": "San Giovanni de Matha e san Felice di Valois",
"Sts. John of Matha, Felix of Valois, John Baptist of the Conception": "San Giovanni de Matha, san Felice di Valois, san Giovanni Battista della Concezione",
"Sts. Peter Nolasco, Raymond Nonnatus, Mary de Cervellón": "San Pietro Nolasco, san Raimondo Nonnato, santa Maria de Cervellón",
"Sts. Cajetan, Andrew Avellino, Joseph Mary Tomasi": "San Gaetano, sant’Andrea Avellino, san Giuseppe Maria Tomasi",
"Sts. Anthony Mary Zaccaria, Alexander Sauli, Francis Xavier Bianchi": "Sant’Antonio Maria Zaccaria, sant’Alessandro Sauli, san Francesco Saverio Bianchi",
"Sts. Francis Xavier, Peter Canisius, Robert Bellarmine, Aloysius Gonzaga, Isaac Jogues, Peter Claver": "San Francesco Saverio, san Pietro Canisio, san Roberto Bellarmino, san Luigi Gonzaga, sant’Isacco Jogues, san Pietro Claver",
"Sts. Philip Neri, John Henry Newman, Joseph Vaz": "San Filippo Neri, san John Henry Newman, san Giuseppe Vaz",
"Sts. Joseph Calasanz, Pompilio Pirrotti": "San Giuseppe Calasanzio, san Pompilio Pirrotti",
"Sts. Vincent de Paul, Louise de Marillac, Catherine Labouré, Justin de Jacobis": "San Vincenzo de’ Paoli, santa Luisa de Marillac, santa Caterina Labouré, san Giustino de Jacobis",
"Sts. Paul of the Cross, Gabriel of Our Lady of Sorrows, Gemma Galgani (associated), Charles of Mount Argus": "San Paolo della Croce, san Gabriele dell’Addolorata, santa Gemma Galgani (legata all’ordine), san Carlo di Mount Argus",
"Sts. Alphonsus Liguori, Gerard Majella, John Neumann, Clement Mary Hofbauer; Bls. Zenon Kovalyk, Mykola Charnetskyi": "Sant’Alfonso Maria de’ Liguori, san Gerardo Majella, san Giovanni Neumann, san Clemente Maria Hofbauer; beati Zenone Kovalyk, Mykola Čarnec’kyj",
"Sts. John Bosco, Dominic Savio, Mary Mazzarello": "San Giovanni Bosco, san Domenico Savio, santa Maria Mazzarello",
