"Sts. Jane Frances de Chantal, Margaret Mary Alacoque": "Santa Giovanna Francesca de Chantal, santa Margherita Maria Alacoque",
"c. 1070; recognized 1113": "ca. 1070; riconosciuto nel 1113",
